const names=["Alcornoque", "Adelfa", "Arce japon\u00e9s", "Olivo"];
const latin=["Quercus suber", "Nerium oleander", "Acer palmatum", "Olea europaea"];
const photos=["https://upload.wikimedia.org/wikipedia/commons/f/f5/Quercus_suber_leaves.jpg", "https://upload.wikimedia.org/wikipedia/commons/b/b8/Nerium_oleander_flower_and_leaves.jpg", "https://upload.wikimedia.org/wikipedia/commons/7/7b/Leaves_of_Acer_palmatum_%28Japanese_maple%29.jpg", "https://upload.wikimedia.org/wikipedia/commons/5/5d/Olea_europaea_leaves.jpg"];
const sources=["https://commons.wikimedia.org/wiki/File:Quercus_suber_leaves.jpg", "https://commons.wikimedia.org/wiki/File:Nerium_oleander_flower_and_leaves.jpg", "https://commons.wikimedia.org/wiki/File:Leaves_of_Acer_palmatum_(Japanese_maple).jpg", "https://commons.wikimedia.org/wiki/File:Olea_europaea_leaves.jpg"];
const authors=["Madrone HeHeHe", "Poojasasikumar", "Humoyun Mehridinov", "Prahlad balaji"];
const examples=DATA.examples;
const labels=["Excentricidad", "Relaci\u00f3n de aspecto", "Solidez", "Factor isoperim\u00e9trico"];
function classify(){if(!document.querySelector('#form').reportValidity())return;const x=labels.map((_,i)=>+document.querySelector('#f'+i).value);let n=DATA.tree,path=[];while(!n.p){const left=x[n.f]<=n.t;path.push(`${labels[n.f]}: ${x[n.f]} ${left?'≤':'>'} ${n.t.toFixed(5)}.`);n=left?n.l:n.r}const k=n.p.indexOf(Math.max(...n.p));document.querySelector('#species').textContent=names[k];document.querySelector('#resultphoto').src=photos[k];document.querySelector('#resultphoto').alt='Fotografía de '+names[k];document.querySelector('#resulttext').textContent=latin[k]+' · Mayor probabilidad para estos descriptores.';document.querySelector('#bars').innerHTML=n.p.map((p,i)=>`<div class="barlabel"><span>${names[i]}</span><b>${(p*100).toFixed(1)} %</b></div><div class="track"><div class="fill" style="width:${p*100}%"></div></div>`).join('');document.querySelector('#path').innerHTML=path.map(p=>`<li>${p}</li>`).join('')}
function preset(k){examples[k].forEach((v,i)=>document.querySelector('#f'+i).value=v);classify()}
document.querySelector('#form').addEventListener('submit',e=>{e.preventDefault();classify()});
document.querySelectorAll('[data-preset]').forEach(b=>b.addEventListener('click',()=>preset(+b.dataset.preset)));
document.querySelector('#cards').innerHTML=names.map((n,i)=>`<article class="card"><img loading="lazy" src="${photos[i]}" alt="Fotografía real de ${n}"><div class="cardbody"><p class="eyebrow">ESPECIE 0${i+1}</p><h3>${n}</h3><p>${DATA.counts[i]} muestras reales de ${latin[i]} en este subconjunto. Compara sus medidas con las otras especies en el laboratorio.</p><button type="button" data-card="${i}">Probar un ejemplo ↗</button><div class="cardmeta">Foto: ${authors[i]}<br><a href="${sources[i]}" target="_blank" rel="noopener">Fuente y licencia ↗</a></div></div></article>`).join('');
document.querySelectorAll('[data-card]').forEach(b=>b.addEventListener('click',()=>{preset(+b.dataset.card);document.querySelector('#laboratorio').scrollIntoView({behavior:'smooth'})}));
document.querySelector('#accuracy').textContent=(DATA.accuracy*100).toFixed(1)+' %';document.querySelector('#cv').textContent=(DATA.cv*100).toFixed(1)+' %';document.querySelector('#matrix').innerHTML='<table><caption class="note">Cuatro tipos de plantas</caption><tr><th scope="col">Real / Predicha</th>'+names.map(n=>`<th scope="col">${n}</th>`).join('')+'</tr>'+DATA.matrix.map((row,i)=>`<tr><th scope="row">${names[i]}</th>`+row.map((v,j)=>`<td class="${i===j?'good':''}">${v}</td>`).join('')+'</tr>').join('')+'</table>';
let svg='';for(let i=0;i<=6;i++){let yy=250-i*33;svg+=`<line x1="65" y1="${yy}" x2="865" y2="${yy}" stroke="#e5e9e1"/><text x="48" y="${yy+4}" font-size="11" fill="#657369">${i+1}</text>`}for(let i=0;i<=8;i++)svg+=`<text x="${65+i/8*800}" y="273" text-anchor="middle" font-size="11" fill="#657369">${(.2+i*.1).toFixed(1)}</text>`;svg+='<text x="430" y="296" text-anchor="middle" font-size="12" fill="#657369">Excentricidad (sin unidades)</text><text x="16" y="140" transform="rotate(-90 16 140)" text-anchor="middle" font-size="12" fill="#657369">Relación de aspecto</text>';const colors=['#547f66','#9375ae','#cc9760','#7891a0'];DATA.points.forEach(p=>svg+=`<circle cx="${65+(p.x-.2)/.8*800}" cy="${250-(p.y-1)*33}" r="5" fill="${colors[p.c]}" opacity=".7"><title>${names[p.c]}: excentricidad ${p.x}, relación de aspecto ${p.y}</title></circle>`);document.querySelector('#scatter').innerHTML=svg;classify();
